multi_alignment__snippycore.example_invocation:
workflow {
    // 1PP_* => snippy + snippycore
    multi_alignment__snippycore(getInput().filter( ~/^.*\/1PP_.*/ ), getReferenceUnkeyed('gb'))
    // 2AS_* => snippycore only
    multi_alignment__snippycore_vcf(getInputFolders().filter( ~/^.*\/2AS_.*/ ), getReferenceUnkeyed('gb'))
}

multi_clustering__augur.example_invocation:
workflow {
    reference = getReferenceUnkeyed('gb')      
    multi_clustering__augur(reference, param('metadata'), param('geodata'), reference)
}

multi_clustering__ksnp3.example_invocation:
workflow {
    multi_clustering__ksnp3(getInput(), param('kmers_size'), param('analysis_type'), param('metadata'), param('geodata'));
}
